<?php
$titulo_pagina='Empresa';$estilos_pagina=['/assets/css/jobs.css?v=1'];require_once __DIR__.'/includes/functions.php';$id=(int)($_GET['id']??0);$stmt=$mysqli->prepare('SELECT e.*,(SELECT COUNT(*) FROM seguidores_empresas s WHERE s.empresa_id=e.id) seguidores FROM empresas e WHERE e.id=? AND e.ativo=1');$stmt->bind_param('i',$id);$stmt->execute();$empresa=$stmt->get_result()->fetch_assoc();if(!$empresa){http_response_code(404);die('Empresa não encontrada.');}$stmt=$mysqli->prepare('SELECT * FROM vagas WHERE empresa_id=? AND ativa=1 ORDER BY criado_em DESC');$stmt->bind_param('i',$id);$stmt->execute();$vagas=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);require_once __DIR__.'/includes/header.php';
?>
<div class="container jobs-page"><h1><?php echo sanitizar($empresa['nome_fantasia']); ?> <span class="business-badge">CNPJ</span></h1><p><?php echo nl2br(sanitizar($empresa['descricao'])); ?></p><p><?php echo (int)$empresa['seguidores']; ?> seguidores · <?php echo sanitizar($empresa['cidade'].'/'.$empresa['uf']); ?></p><?php if(usuario_autenticado()&&($_SESSION['tipo_usuario']??'')!=='empresa'): ?><form method="POST" action="/seguir-empresa.php"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="empresa_id" value="<?php echo $id; ?>"><button class="btn">Seguir empresa</button></form><?php endif; ?><h2>Vagas abertas</h2><div class="jobs-grid"><?php foreach($vagas as $vaga): ?><article><h2><?php echo sanitizar($vaga['titulo']); ?></h2><p><?php echo sanitizar($vaga['modalidade']); ?></p><a class="btn" href="/candidatar.php?vaga=<?php echo (int)$vaga['id']; ?>">Candidatar-se</a></article><?php endforeach; ?></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
